"""Sample generated images and get a structured qualitative review from a vision model.

Composes:
  - image_locations.sample_images  (which images to look at, preferring failures)
  - eval_api_key.resolve_eval_api_key + TOKENHUB_BASE_URL  (key + gateway, repo-relative)

Adds image-INPUT support that tokenhub_call.py lacks (it only generates images): the
OpenAI-style chat API with base64 image_url content parts. NEVER raises on a model/key
failure — returns a record with an ``error`` field so the report still renders the scores.
"""
from __future__ import annotations

import argparse
import json
import os

import image_locations
import image_thumb
import output_paths
import eval_api_key

RUBRIC = (
    "You are reviewing images generated by a text-to-image model for an eval report. "
    "Assess the SET of images and return STRICT JSON with these string fields. "
    "IMPORTANT: write every field VALUE (and the failure category/note) in 简体中文 — "
    "but keep the JSON KEYS exactly as the English names below.\n"
    "  defects: obvious breakage — anatomy errors, color collapse, duplication, ghosting.\n"
    "  prompt_alignment: typical prompt requirements met (objects, attributes, count, "
    "spatial relations, text rendering)? note misses.\n"
    "  aesthetics: composition, lighting, sharpness, style consistency.\n"
    "  text_rendering: garbled/misspelled text, and SPECIFICALLY whether a Chinese prompt "
    "produced English glyphs or vice versa.\n"
    "  artifacts: other generation artifacts (watermarks, grid seams, noise).\n"
    "Also return failure_examples: a JSON array of {index, category, note} pointing at the "
    "worst images by 1-based position in the order shown (category/note in 简体中文). "
    "Return ONLY a JSON object with keys: defects, prompt_alignment, aesthetics, "
    "text_rendering, artifacts, failure_examples."
)

# Image-editing (it2i) review: each sample is a (instruction, ORIGINAL image, RESULT image)
# triple, so the model can judge the edit, not just the output. Findings in 简体中文; keys English.
IT2I_RUBRIC = (
    "You are reviewing image EDITS for an eval report. For each sample you are given the edit "
    "INSTRUCTION, the ORIGINAL input image, and the model's RESULT image. Judge the edit "
    "(not just the output). Return STRICT JSON; write every VALUE in 简体中文, keep the English KEYS.\n"
    "  instruction_following: 是否按编辑指令正确完成了要求的修改？指出没做到的。\n"
    "  preservation: 指令无关的区域 / 主体身份 / 背景是否被保留（没有被误改 / 丢失）？\n"
    "  edit_quality: 编辑是否自然、无缝、清晰（边缘、光照、融合是否合理）？\n"
    "  defects: 崩坏 / 伪影 / 重影 / 颜色塌陷等生成问题。\n"
    "Also return failure_examples: a JSON array of {index, category, note} (category/note in "
    "简体中文) pointing at the worst RESULTS by 1-based sample position. "
    "Return ONLY a JSON object with keys: instruction_following, preservation, edit_quality, "
    "defects, failure_examples."
)

T2I_DIMS = ("defects", "prompt_alignment", "aesthetics", "text_rendering", "artifacts")
IT2I_DIMS = ("instruction_following", "preservation", "edit_quality", "defects")


def _build_messages(images):
    # Downscale each image to a JPEG data URL so 12 full-res images stay well under the
    # tokenhub gateway's 50MB request limit (see image_thumb).
    content = [{"type": "text", "text": RUBRIC}]
    for i, p in enumerate(images, 1):
        content.append({"type": "text", "text": f"Image {i}: {os.path.basename(p)}"})
        content.append({"type": "image_url", "image_url": {"url": image_thumb.to_data_url(p, max_edge=768)}})
    return [{"role": "user", "content": content}]


def _build_messages_it2i(bench, images):
    # For each result image, attach its edit instruction + original input image so the model
    # can assess the EDIT. Falls back to result-only if the original/instruction is missing.
    content = [{"type": "text", "text": IT2I_RUBRIC}]
    for i, p in enumerate(images, 1):
        ctx = image_locations.it2i_context(bench, p)
        instr = ctx.get("instruction") or "(指令缺失)"
        content.append({"type": "text", "text": f"样本 {i} 编辑指令：{instr}"})
        if ctx.get("original"):
            content.append({"type": "text", "text": "原图："})
            content.append({"type": "image_url",
                            "image_url": {"url": image_thumb.to_data_url(ctx["original"], max_edge=768)}})
        content.append({"type": "text", "text": "编辑结果："})
        content.append({"type": "image_url", "image_url": {"url": image_thumb.to_data_url(p, max_edge=768)}})
    return [{"role": "user", "content": content}]


def review(bench, results_root, model_name="model", step_name="step", *,
           samples=12, model="gpt-5.5", prefer_failures=True, dry_run=False, language=None):
    images = image_locations.sample_images(bench, results_root, k=samples,
                                           prefer_failures=prefer_failures, language=language)
    record = {
        "benchmark": bench, "model_name": model_name, "step_name": step_name,
        "n_sampled": len(images), "model_used": model,
        "findings": {}, "failure_examples": [],
    }
    if not images:
        record["error"] = f"no generated images found under {results_root}"
        return record
    is_it2i = bench in image_locations.IT2I_BENCHES
    dims = IT2I_DIMS if is_it2i else T2I_DIMS
    try:
        # reads image bytes — guarded to honor never-raise
        messages = _build_messages_it2i(bench, images) if is_it2i else _build_messages(images)
        if dry_run:
            record["_messages_preview"] = {"n_content_parts": len(messages[0]["content"]),
                                           "is_it2i": is_it2i}
            return record
        from openai import OpenAI
        key = eval_api_key.resolve_eval_api_key()
        client = OpenAI(api_key=key, base_url=eval_api_key.TOKENHUB_BASE_URL)
        resp = client.chat.completions.create(
            model=model, messages=messages,
            response_format={"type": "json_object"}, max_tokens=4000,
        )
        data = json.loads(resp.choices[0].message.content)
    except Exception as e:  # never block the scores table
        record["error"] = f"{type(e).__name__}: {e}"
        return record
    for dim in dims:
        record["findings"][dim] = str(data.get(dim, "")).strip()
    for ex in data.get("failure_examples") or []:
        idx = ex.get("index")
        path = images[idx - 1] if isinstance(idx, int) and 1 <= idx <= len(images) else None
        record["failure_examples"].append({
            "path": path or "?",
            "category": str(ex.get("category", "?")),
            "note": str(ex.get("note", "")),
        })
    return record


def _main():
    ap = argparse.ArgumentParser(description="Qualitative vision review of generated images.")
    ap.add_argument("--bench", required=True, choices=sorted(image_locations.BENCH_IMAGE_GLOBS))
    ap.add_argument("--results-root", default=None)
    ap.add_argument("--output-base", default=None)
    ap.add_argument("--model-name", default="model")
    ap.add_argument("--step-name", default="step")
    ap.add_argument("--samples", type=int, default=12)
    ap.add_argument("--model", default="gpt-5.5")
    ap.add_argument("--no-prefer-failures", action="store_true")
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--out", default=None)
    # knobs for deriving the root (mirror collect_results.py)
    ap.add_argument("--image-size", default="512")
    ap.add_argument("--cfg-scale", default="4.0")
    ap.add_argument("--cfg-norm", default="global")
    ap.add_argument("--txt-cfg", default="4.0")
    ap.add_argument("--img-cfg", default="1.0")
    ap.add_argument("--cfg-renorm", default="global")
    ap.add_argument("--timestep-shift", default="3.0")
    ap.add_argument("--mode", default="en")
    ap.add_argument("--language", default=None,
                    help="narrow sampling to one language for language-partitioned benchmarks (e.g. oneigbench en|zh)")
    ap.add_argument("--output-subdir", default=None)
    args = ap.parse_args()

    results_root = args.results_root
    if results_root is None:
        if args.output_base is None:
            ap.error("either --results-root or --output-base is required")
        results_root = output_paths.derive_output_root(
            bench=args.bench, output_base=args.output_base,
            model_name=args.model_name, step_name=args.step_name,
            image_size=args.image_size, cfg_scale=args.cfg_scale, cfg_norm=args.cfg_norm,
            txt_cfg=args.txt_cfg, img_cfg=args.img_cfg, cfg_renorm=args.cfg_renorm,
            timestep_shift=args.timestep_shift, mode=args.mode, output_subdir=args.output_subdir,
        )

    record = review(args.bench, results_root, model_name=args.model_name,
                    step_name=args.step_name, samples=args.samples, model=args.model,
                    prefer_failures=not args.no_prefer_failures, dry_run=args.dry_run,
                    language=args.language)
    payload = json.dumps(record, indent=2, ensure_ascii=False)
    print(payload)
    if args.out:
        with open(args.out, "w", encoding="utf-8") as f:
            f.write(payload)


if __name__ == "__main__":
    _main()
